function getNotaReg(codInsc,idMateria,ano){
  return DB.notas.find(n=>String(n.CodInscricao)===String(codInsc) && String(n.CodMateria)===String(idMateria) && n.Ano===(ano||getInsc(codInsc)?.Ano||DB.config.anoActivo));
}
function criarNotaReg(codInsc,idMateria,ano){
  const nova={IdNota:nextId(DB.notas,'IdNota'),CodInscricao:Number(codInsc),CodMateria:Number(idMateria),
    Ano:ano||DB.config.anoActivo,
    I_Trimestre:{MAC:null,NPP:null,NPT:null},
    II_Trimestre:{MAC:null,NPP:null,NPT:null},
    III_Trimestre:{MAC:null,NPP:null,NPT:null},
    ExameFinal:null,ExameRecurso:null,Locked:false,CodProfessor:'',DataLancamento:null};
  DB.notas.push(nova); return nova;
}
function mediaTrimestre(nota,periodoKey){
  if(!nota||!nota[periodoKey]) return null;
  const t=nota[periodoKey];
  const v=[t.MAC,t.NPP,t.NPT].filter(x=>x!==null&&x!==undefined&&x!=='');
  if(!v.length) return null;
  return int(v.reduce((s,x)=>s+num(x),0)/v.length);
}
function mediaAnual(nota){
  if(!nota) return null;
  const ms=PERIODOS.map(p=>mediaTrimestre(nota,p.replace(' ','_'))).filter(v=>v!==null);
  if(!ms.length) return null;
  return int(ms.reduce((a,b)=>a+b,0)/ms.length);
}
function notaFinalDisciplina(nota){
  const ma=mediaAnual(nota); if(ma===null) return null;
  const ef=nota.ExameFinal;
  const pma=DB.config.pesoMediaAnual??0.6;
  const pef=DB.config.pesoExameFinal??0.4;
  if(ef===null||ef===undefined||ef==='') return ma;
  return int(ma*pma + num(ef)*pef);
}
function notaFinalComRecurso(nota){
  const nf=notaFinalDisciplina(nota);
  if(nota.ExameRecurso!==null && nota.ExameRecurso!==undefined && nota.ExameRecurso!==''){
    return Math.max(nf||0, int(nota.ExameRecurso));
  }
  return nf;
}

/* Meses devidos no ano lectivo */
function mesesDevidos(anoLectivo){
  const anoInfo=DB.anosLectivos.find(a=>a.Ano===anoLectivo);
  if(!anoInfo || !anoInfo.DataAbertura) return 3;
  const ab=new Date(anoInfo.DataAbertura), hj=new Date();
  const diff=(hj.getFullYear()-ab.getFullYear())*12 + (hj.getMonth()-ab.getMonth()) + 1;
  return Math.min(10, Math.max(1, diff));
}
function propinasPagas(codAluno,anoLectivo){
  const anoInfo=DB.anosLectivos.find(a=>a.Ano===anoLectivo);
  const anoAb=anoInfo?String(anoInfo.DataAbertura).slice(0,4):'';
  return DB.pagamentos.filter(p=>p.CodAluno===codAluno && p.Referente==='Propina Mensal'
    && String(p.Data).slice(0,4)>=anoAb).length;
}

