function formTurma(id){
  if(!canEdit('turmas')){ toast('Sem permissão','err'); return; }
  const t=id?getTurma(id):null;
  const d=t||{CodTurma:nextCode(DB.turmas,'CodTurma','T'),Turma:'',Classe:'10ª Classe',Curso:'CUR001',
    Ano:DB.config.anoActivo,Turno:'Manhã',Sala:'',Capacidade:40,CodFuncionario:'',CodEscola:DB.scope.schoolId,Estado:'Activa'};
  openModal({
    title:t?`✏️ Editar Turma ${t.CodTurma}`:'➕ Nova Turma',
    body:`<div class="form-grid g2">
      <div class="campo"><label>Código *</label><input id="t_Cod" value="${esc(d.CodTurma)}" ${t?'readonly':''}></div>
      <div class="campo"><label>Designação *</label><input id="t_Turma" value="${esc(d.Turma)}"></div>
      <div class="campo"><label>Ano *</label><input id="t_Ano" value="${esc(d.Ano)}"></div>
      <div class="campo"><label>Classe *</label><select id="t_Classe">${DB.classes.map(c=>`<option ${d.Classe===c.Classe?'selected':''}>${esc(c.Classe)}</option>`).join('')}</select></div>
      <div class="campo"><label>Curso *</label><select id="t_Curso">${DB.cursos.map(c=>`<option value="${esc(c.CodCurso)}" ${d.Curso===c.CodCurso?'selected':''}>${esc(c.Nome)}</option>`).join('')}</select></div>
      <div class="campo"><label>Turno</label><select id="t_Turno">${TURNOS.map(x=>`<option ${d.Turno===x?'selected':''}>${x}</option>`).join('')}</select></div>
      <div class="campo"><label>Sala</label><input id="t_Sala" value="${esc(d.Sala||'')}"></div>
      <div class="campo"><label>Capacidade</label><input type="number" id="t_Cap" value="${d.Capacidade||40}"></div>
      <div class="campo span2"><label>Director de Turma</label><select id="t_Dir"><option value="">—</option>
        ${DB.funcionarios.filter(f=>['Docente','Director'].includes(f.Categoria)).map(f=>`<option value="${esc(f.IdFuncionario)}" ${d.CodFuncionario===f.IdFuncionario?'selected':''}>${esc(f.Nome)}</option>`).join('')}</select></div>
    </div>`,
    buttons:[{l:'Cancelar',cls:'btn-ghost',fn:closeModal},{l:'💾 Guardar',cls:'btn-primary',fn:()=>{
      const obj={CodTurma:$('#t_Cod').value.trim(),Turma:$('#t_Turma').value.trim(),Ano:$('#t_Ano').value.trim(),
        Classe:$('#t_Classe').value,Curso:$('#t_Curso').value,Turno:$('#t_Turno').value,Sala:$('#t_Sala').value.trim(),
        Capacidade:num($('#t_Cap').value)||40,CodFuncionario:$('#t_Dir').value||'',CodEscola:DB.scope.schoolId,Estado:'Activa'};
      if(!obj.CodTurma||!obj.Turma){toast('Preencha','err');return;}
      if(t){Object.assign(t,obj);}else{if(DB.turmas.some(x=>x.CodTurma===obj.CodTurma)){toast('Existe','err');return;}DB.turmas.push(obj);}
      saveDB();closeModal();renderView();toast('Guardada.');}}]});}
function apagarTurma(id){ if(!canEdit('turmas')) return;
  confirmar('Eliminar turma?',()=>{DB.turmas=DB.turmas.filter(t=>t.CodTurma!==id);saveDB();renderView();},'🗑 Eliminar');}
function verTurma(id){
  const t=getTurma(id); if(!t) return;
  const alunos=alunosDaTurma(id,t.Ano);
  const c=getCurso(t.Curso);
  openModal({
    title:'👥 Turma '+t.Turma+' ('+t.CodTurma+')',
    sub:t.Classe+' · '+(c?c.Nome:'')+' · '+t.Turno+' · '+alunos.length+' alunos',
    size:'lg',
    body:`<div class="tabela-wrap"><table class="tabela">
      <thead><tr><th>#</th><th>ID</th><th>Nome</th><th>Sexo</th><th>Idade</th><th>Estado</th></tr></thead>
      <tbody>${alunos.length?alunos.map((x,i)=>{
        const stCls=x.ins.Estado==='Pendente'?'badge-warn':x.ins.Estado==='Matriculado'?'badge-ok':'badge-gray';
        return `<tr><td>${i+1}</td><td>${esc(x.aluno.IdAluno)}</td>
        <td><b>${esc(x.aluno.Nome)}</b></td><td>${x.aluno.Sexo}</td>
        <td>${idade(x.aluno.DataNa)}</td>
        <td><span class="badge ${stCls}">${esc(x.ins.Estado)}</span></td></tr>`;
      }).join(''):'<tr><td colspan="6" class="vazio">Sem alunos.</td></tr>'}</tbody>
    </table></div>`,
    buttons:[{l:'Fechar',cls:'btn-ghost',fn:closeModal},{l:'🖨 Imprimir Lista',cls:'btn-gold',fn:()=>{closeModal();imprimirListaTurma(id);}}]
  });
}

