/* --- FUNCIONÁRIOS --- */
VIEWS.funcionarios = el=>{
  const q=(state.filtro_func||'').toLowerCase();
  let list=DB.funcionarios.slice().sort((a,b)=>a.Nome.localeCompare(b.Nome));
  if(q) list=list.filter(f=>(f.Nome+f.IdFuncionario+f.Especialidade).toLowerCase().includes(q));
  el.innerHTML=`<div class="toolbar">
    <input class="search" id="qFunc" placeholder="Pesquisar..." value="${esc(state.filtro_func||'')}">
    <div class="spacer"></div>
    <button class="btn btn-ghost" data-sige-click="${bind((event,element)=>{return imprimirListaFuncionarios()})}">🖨 Imprimir</button>
    ${canEdit('funcionarios')?`<button class="btn btn-primary" data-sige-click="${bind((event,element)=>{return formFuncionario()})}">➕ Novo</button>`:''}</div>
  <div class="card"><div class="card-body np"><div class="tabela-wrap"><table class="tabela">
    <thead><tr><th>ID</th><th>Nome</th><th>Categoria</th><th>Especialidade</th><th>Nível</th><th>Regime</th><th style="text-align:right">Acções</th></tr></thead>
    <tbody>${list.map(f=>`<tr><td><b>${esc(f.IdFuncionario)}</b></td><td>${esc(f.Nome)}</td>
      <td><span class="badge ${f.Categoria==='Docente'?'badge-info':'badge-gray'}">${esc(f.Categoria)}</span></td>
      <td>${esc(f.Especialidade)}</td><td>${esc(f.Nivel)}</td><td>${esc(f.Regime)}</td>
      <td class="acoes">${canEdit('funcionarios')?`<button class="btn btn-ghost btn-xs" data-sige-click="${bind((event,element)=>{return formFuncionario((f.IdFuncionario))})}">✎</button>
        <button class="btn btn-danger btn-xs" data-sige-click="${bind((event,element)=>{return apagarFuncionario((f.IdFuncionario))})}">🗑</button>`:''}</td></tr>`).join('')}</tbody></table></div></div></div>`;
  const inp=$('#qFunc'); if(inp) inp.oninput=e=>{state.filtro_func=e.target.value;renderView();};};
function formFuncionario(id){
  if(!canEdit('funcionarios')) return;
  const f=id?getFunc(id):null;
  const d=f||{IdFuncionario:nextCode(DB.funcionarios,'IdFuncionario','FUN'),Sexo:'M',DataN:'1985-01-01',
    Data:today(),Categoria:'Docente',Nivel:'Licenciatura',Regime:'Efectivo'};
  const F=(l,k,t='text',o={})=>{const v=d[k]!=null?d[k]:'';return `<div class="campo${o.full?' full':''}"><label>${l}${o.req?' *':''}</label><input id="f_${k}" type="${t}" value="${esc(v)}" ${o.ro?'readonly':''}></div>`;};
  const S=(l,k,opts,req)=>{const v=d[k]!=null?d[k]:'';return `<div class="campo"><label>${l}${req?' *':''}</label><select id="f_${k}"><option value="">—</option>${opts.map(o=>`<option value="${esc(o)}" ${String(v)===String(o)?'selected':''}>${esc(o)}</option>`).join('')}</select></div>`;};
  openModal({title:f?'✏️ Editar':'➕ Novo Funcionário',size:'lg',
    body:`<div class="form-grid g2">
      <div class="form-sec">📋 Dados Pessoais</div>
      ${F('Nº Funcionário','IdFuncionario','text',{req:1,ro:!!f})}${F('Nome Completo','Nome','text',{req:1})}
      ${S('Sexo','Sexo',['M','F'],1)}${F('Data Nasc.','DataN','date',{req:1})}
      ${F('BI','BI')}${F('NIF','NIF')}${F('Telemóvel','Movel','tel',{req:1})}${F('Email','Email','email')}
      <div class="form-sec">💼 Profissional</div>
      ${S('Nível','Nivel',['Básico','Médio','Licenciatura','Mestrado','Doutoramento'],1)}
      ${F('Especialidade','Especialidade','text',{req:1})}
      ${S('Categoria','Categoria',['Docente','Director','Subdirector','Secretario','Contabilista','Auxiliar'],1)}
      ${S('Regime','Regime',['Efectivo','Tempo Integral','Tempo Parcial','Contrato'],1)}
      ${F('Data Admissão','Data','date')}
    </div>`,
    buttons:[{l:'Cancelar',cls:'btn-ghost',fn:closeModal},{l:'💾 Guardar',cls:'btn-primary',fn:()=>{
      const cs=['IdFuncionario','Nome','Sexo','DataN','BI','NIF','Movel','Email','Nivel','Especialidade','Categoria','Regime','Data'];
      const obj={};cs.forEach(c=>{const e=$('#f_'+c);obj[c]=e?e.value.trim():'';});
      if(!obj.Nome){toast('Indique','err');return;}
      if(f){Object.assign(f,obj);}else{if(DB.funcionarios.some(x=>x.IdFuncionario===obj.IdFuncionario)){toast('Existe','err');return;}DB.funcionarios.push(obj);}
      saveDB();closeModal();renderView();toast('Guardado.');}}]});}
function apagarFuncionario(id){ if(!canEdit('funcionarios')) return;
  confirmar('Eliminar?',()=>{DB.funcionarios=DB.funcionarios.filter(f=>f.IdFuncionario!==id);saveDB();renderView();},'🗑 Eliminar');}

