VIEWS['dividas-turma'] = el=>{
  const turmas=DB.turmas.filter(t=>t.Ano===(state.ano_divida||DB.config.anoActivo));
  if(!turmas.length){el.innerHTML=yearSelect('dv_ano',state.ano_divida||DB.config.anoActivo,'ano_divida')+'<div class="card"><div class="vazio">Sem turmas neste ano.</div></div>';return;}
  if(!state.dividaTurma || !turmas.some(t=>t.CodTurma===state.dividaTurma)) state.dividaTurma=turmas[0].CodTurma;
  const codTurma=state.dividaTurma;
  const t=getTurma(codTurma);
  const alunos=alunosDaTurma(codTurma,t.Ano);
  const mesAtual=new Date().getMonth()+1;
  const mesesDecorridos=Math.max(1,Math.min(10, mesAtual<9?1:mesAtual-8));
  const rows=alunos.map(x=>{
    const cl=getClasse(x.ins.Classe,x.ins.Ano),b=DB.propinas[x.ins.IdInscricao];
    return {x,cl,pagos:Math.max(0,b.mesesDevidos-b.mesesEmFalta),devidos:b.mesesDevidos,falta:b.mesesEmFalta,valorDevido:b.divida};
  }).filter(r=>r.falta>0);
  el.innerHTML=`
  <div class="toolbar">${yearSelect('dv_ano',state.ano_divida||DB.config.anoActivo,'ano_divida')}
    <select id="dv_turma">
      ${turmas.map(t=>`<option value="${esc(t.CodTurma)}" ${codTurma===t.CodTurma?'selected':''}>${esc(t.CodTurma)} · ${esc(t.Turma)} (${esc(t.Classe)})</option>`).join('')}
    </select>
    <div class="spacer"></div>
    <button class="btn btn-gold" data-sige-click="${bind((event,element)=>{return imprimirDividasTurma((codTurma))})}">🖨 Imprimir Lista</button>
  </div>
  <div class="info-box r">
    <b>⚠️ Propinas em Atraso:</b> ${rows.length} de ${alunos.length} alunos ·
    <b>Total em dívida:</b> ${money(rows.reduce((s,r)=>s+r.valorDevido,0))}
  </div>
  <div class="card"><div class="card-body np"><div class="tabela-wrap"><table class="tabela">
    <thead><tr><th>#</th><th>Nº Processo</th><th>Nome</th><th>Sexo</th><th>Idade</th><th class="c">Devidos</th><th class="c">Pagos</th><th class="c">Falta</th><th style="text-align:right">Valor</th></tr></thead>
    <tbody>${rows.length?rows.map((r,i)=>`<tr>
      <td>${i+1}</td>
      <td>${esc(r.x.aluno.IdAluno)}</td>
      <td><b>${esc(r.x.aluno.Nome)}</b></td>
      <td>${r.x.aluno.Sexo}</td>
      <td>${idade(r.x.aluno.DataNa)}</td>
      <td class="c">${r.devidos}</td>
      <td class="c">${r.pagos}</td>
      <td class="c"><b class="nota-bad">${r.falta}</b></td>
      <td style="text-align:right"><b style="color:var(--vermelho)">${money(r.valorDevido)}</b></td>
    </tr>`).join(''):`<tr><td colspan="9" class="vazio"><span class="big">✅</span>Não há propinas em atraso.</td></tr>`}</tbody>
  </table></div></div></div>`;
  $('#dv_turma').onchange=e=>{state.dividaTurma=e.target.value;renderView();};
};

