function apagarUsuario(id){ if(!canEdit('usuarios')) return;
  if(id===session.IdUsuario){toast('Não pode eliminar-se','err');return;}
  confirmar('Eliminar?',()=>{DB.usuarios=DB.usuarios.filter(u=>u.IdUsuario!==id);saveDB();renderView();},'🗑 Eliminar');}

