VIEWS['anos-lectivos'] = el=>{
  el.innerHTML=`<div class="toolbar"><div class="spacer"></div>
    ${canEdit('anos-lectivos')?`<button class="btn btn-primary" data-sige-click="${bind((event,element)=>{return formAno()})}">➕ Novo Ano</button>`:''}</div>
  <div class="card"><div class="card-body np"><div class="tabela-wrap"><table class="tabela">
    <thead><tr><th>Ano</th><th>Estado</th><th>Abertura</th><th>Fecho</th><th>Inscrições</th><th>Pendentes</th><th style="text-align:right">Acções</th></tr></thead>
    <tbody>${DB.anosLectivos.map(a=>`<tr><td><b>${esc(a.Ano)}</b>${a.Ano===DB.config.anoActivo?' <span class="badge badge-ok">Activo</span>':''}</td>
      <td><span class="badge ${a.Estado==='Aberto'?'badge-ok':a.Estado==='Encerrado'?'badge-gray':'badge-warn'}">${esc(a.Estado)}</span></td>
      <td>${dt(a.DataAbertura)}</td><td>${dt(a.DataFecho)}</td>
      <td>${DB.inscricoes.filter(i=>i.Ano===a.Ano).length}</td>
      <td><span class="badge badge-warn">${DB.inscricoes.filter(i=>i.Ano===a.Ano && i.Estado==='Pendente').length}</span></td>
      <td class="acoes">${canEdit('anos-lectivos')?`${a.Ano!==DB.config.anoActivo?`<button class="btn btn-ok btn-xs" data-sige-click="${bind((event,element)=>{return activarAno((a.Ano))})}">✓ Activar</button>`:''}`:''}</td></tr>`).join('')}</tbody>
  </table></div></div></div>`;};
function formAno(){
  if(!canEdit('anos-lectivos')) return;
  openModal({title:'Novo Ano Lectivo',size:'sm',
    body:`<div class="form-grid">
      <div class="campo"><label>Ano *</label><input id="an_Ano" placeholder="Ex.: 2026/2027"></div>
      <div class="campo"><label>Estado</label><select id="an_Estado">${['Planeado','Aberto','Encerrado'].map(e=>`<option>${e}</option>`).join('')}</select></div>
      <div class="campo"><label>Abertura</label><input type="date" id="an_Abertura" value="${today()}"></div>
      <div class="campo"><label>Fecho</label><input type="date" id="an_Fecho"></div>
    </div>`,
    buttons:[{l:'Cancelar',cls:'btn-ghost',fn:closeModal},{l:'💾 Guardar',cls:'btn-primary',fn:()=>{
      const obj={Ano:$('#an_Ano').value.trim(),Estado:$('#an_Estado').value,DataAbertura:$('#an_Abertura').value,DataFecho:$('#an_Fecho').value};
      if(!obj.Ano){toast('Indique','err');return;}
      DB.anosLectivos.push(obj);saveDB();closeModal();renderView();toast('Criado.');}}]});}
function activarAno(ano){
  if(!canEdit('anos-lectivos')) return;
  confirmar(`Activar <b>${ano}</b>?`,()=>{DB.config.anoActivo=ano;DB.anosLectivos.forEach(a=>{if(a.Ano===ano)a.Estado='Aberto';});
  saveDB();$('#anoChip').textContent='Ano Lectivo '+ano;renderView();toast('Activado.');},'✓ Activar',false);}

