function guardarConfig(){const g=k=>{const e=$('#cfg_'+k);return e?e.value.trim():'';};
  ['escolaNome','escolaNIF','escolaTelefone','escolaEndereco','escolaMunicipio','escolaEmail','escolaDiretor','anoActivo'].forEach(k=>DB.config[k]=g(k));
  DB.config.notaMinima=num(g('notaMinima'));DB.config.pesoMediaAnual=num(g('pesoMediaAnual'));DB.config.pesoExameFinal=num(g('pesoExameFinal'));
  saveDB();$('#anoChip').textContent='Ano Lectivo '+DB.config.anoActivo;toast('Guardado.');}




