function imprimirListaTurma(id){
  const t=getTurma(id); if(!t) return;
  const al=alunosDaTurma(id,t.Ano);
  const c=getCurso(t.Curso);
  let h=`<div class="prt">${prtHeader()}
    <div class="prt-title">Lista Nominal — Turma ${esc(t.Turma)}</div>
    <div class="prt-sub">${esc(c?c.Nome:'')} · ${esc(t.Classe)} · ${esc(t.Turno)} · ${esc(t.Ano)} · ${al.length} alunos</div>
    <table class="prt-tabela"><thead><tr>
      <th class="c">#</th><th class="c">Nº Processo</th><th>Nome do Aluno</th>
      <th class="c">Sexo</th><th class="c">Idade</th><th class="c">Estado</th><th>Assinatura</th></tr></thead>
    <tbody>${al.map((x,i)=>`<tr><td class="c">${i+1}</td>
      <td class="c">${esc(x.aluno.IdAluno)}</td><td>${esc(x.aluno.Nome)}</td>
      <td class="c">${x.aluno.Sexo}</td><td class="c">${idade(x.aluno.DataNa)}</td>
      <td class="c">${esc(x.ins.Estado)}</td><td></td></tr>`).join('')}</tbody></table>
    <p style="font-size:11px"><b>Total:</b> ${al.length} · <b>M:</b> ${al.filter(x=>x.aluno.Sexo==='M').length} · <b>F:</b> ${al.filter(x=>x.aluno.Sexo==='F').length}</p>
    ${prtAss(['O Director de Turma','A Direcção'])}${prtFooter()}</div>`;
  imprimir(h,'Lista Turma '+t.Turma);
}

function imprimirListaTurmas(){
  let h=`<div class="prt">${prtHeader()}
    <div class="prt-title">Mapa de Turmas</div>
    <div class="prt-sub">Ano Lectivo ${esc((state.ano_turma||DB.config.anoActivo))}</div>
    <table class="prt-tabela"><thead><tr><th>Código</th><th>Turma</th><th>Classe</th><th>Curso</th><th>Turno</th><th>Sala</th><th>Director</th><th class="c">Nº Alunos</th></tr></thead>
    <tbody>${DB.turmas.filter(t=>t.Ano===(state.ano_turma||DB.config.anoActivo)).map(t=>{
      const c=getCurso(t.Curso); const f=getFunc(t.CodFuncionario);
      const n=alunosDaTurma(t.CodTurma,t.Ano).length;
      return `<tr><td class="c">${esc(t.CodTurma)}</td><td class="c">${esc(t.Turma)}</td>
        <td class="c">${esc(t.Classe)}</td><td>${esc(c?c.Nome:'')}</td>
        <td class="c">${esc(t.Turno)}</td><td class="c">${esc(t.Sala||'')}</td>
        <td>${esc(f?f.Nome:'')}</td><td class="c">${n}</td></tr>`;
    }).join('')}</tbody></table>
    ${prtAss(['A Secretaria','A Direcção'])}${prtFooter()}</div>`;
  imprimir(h,'Mapa de Turmas');
}



