function imprimirMapaPagamentos(){
  const list=paymentsForYear(state.ano_pag||DB.config.anoActivo).slice().sort((a,b)=>String(a.Data).localeCompare(String(b.Data)));
  const tot=list.reduce((s,p)=>s+num(p.Valor),0);
  const porRef={};
  list.forEach(p=>{porRef[p.Referente]=(porRef[p.Referente]||0)+num(p.Valor);});
  let h=`<div class="prt">${prtHeader()}
    <div class="prt-title">Mapa de Pagamentos</div>
    <div class="prt-sub">${list.length} recibos · Total: ${money(tot)}</div>
    <h4 style="color:#0b3d6b;font-size:12.5px;margin:10px 0 6px">Resumo por Rubrica</h4>
    <table class="prt-tabela" style="width:60%"><tbody>${Object.entries(porRef).map(([k,v])=>`<tr><td>${esc(k)}</td><td class="r">${money(v)}</td></tr>`).join('')}
    <tr><td><b>TOTAL</b></td><td class="r"><b>${money(tot)}</b></td></tr></tbody></table>
    ${prtAss(['O Tesoureiro','A Direcção'])}${prtFooter()}</div>`;
  imprimir(h,'Mapa de Pagamentos');
}

/* --- LISTA COMPLETA DE PAGAMENTOS DE UM ALUNO --- */
function imprimirTodosPagamentosAluno(idAluno,year=state.ano_pag||DB.config.anoActivo){
 if(!canEdit('pagamentos'))throw Error('Sem permissão para consultar pagamentos.');
  const a=getAluno(idAluno); if(!a) return;
  const pags=paymentsForYear(year).filter(p=>p.CodAluno===idAluno).sort((x,y)=>String(x.Data).localeCompare(String(y.Data)));
  const tot=pags.reduce((s,p)=>s+num(p.Valor),0);
  const ins=DB.inscricoes.find(i=>i.CodAluno===idAluno && i.Ano===year);
  const cl=ins?getClasse(ins.Classe,ins.Ano):null;
  let h=`<div class="prt">${prtHeader()}
    <div class="prt-title">Lista de Pagamentos do Aluno</div>
    <div class="prt-sub">Ano Lectivo ${esc(year)}</div>
    <div class="prt-info">
      <div><b>Aluno:</b> ${esc(a.Nome)}</div>
      <div><b>Idade:</b> ${idade(a.DataNa)} anos</div>
      <div><b>Nº Processo:</b> ${esc(a.IdAluno)}</div>
      <div><b>Classe:</b> ${ins?esc(ins.Classe):'—'}</div>
      <div><b>Turma:</b> ${ins?esc(ins.Turma||''):'—'}</div>
      <div><b>Curso:</b> ${esc(getCurso(ins?.CodCurso)?.Nome||'—')}</div><div><b>Turno:</b> ${ins?esc(ins.Turno):'—'}</div>
    </div>
    ${pags.length?`
    <table class="prt-tabela"><thead><tr>
      <th class="c">#</th><th>Talão</th><th>Data</th><th>Referente</th><th>Mês</th><th>Forma</th><th class="r">Valor</th></tr></thead>
    <tbody>${pags.map((p,i)=>`<tr>
      <td class="c">${i+1}</td><td class="c">${esc(p.Talao)}</td>
      <td class="c">${dt(p.Data)}</td><td>${esc(p.Referente)}</td>
      <td class="c">${esc(p.Mes||'')}</td><td class="c">${esc(p.FormaPagamento||'')}${['Cheque','Transferência'].includes(p.FormaPagamento)?'<br>Nº '+esc(p.NumeroCheque||'—'):''}</td>
      <td class="r">${money(p.Valor)}</td></tr>`).join('')}</tbody>
    <tfoot><tr><td colspan="6" style="text-align:right"><b>TOTAL PAGO NO ANO:</b></td>
      <td class="r"><b>${money(tot)}</b></td></tr></tfoot></table>
    ${cl?`<p style="font-size:11px;margin-top:8px"><b>Propina mensal da classe:</b> ${money(cl.Propina)}</p>`:''}
    `:'<p style="text-align:center;color:#666;padding:20px">Nenhum pagamento registado.</p>'}
    ${prtAss(['O Tesoureiro(a)','A Direcção'])}${prtFooter(year)}</div>`;
  imprimir(h,'Pagamentos de '+a.Nome);
}

