/* --- DÍVIDAS POR TURMA --- */
function imprimirDividasTurma(codTurma){
  const t=getTurma(codTurma); if(!t) return;
  const alunos=alunosDaTurma(codTurma,t.Ano);
  const mesAtual=new Date().getMonth()+1;
  const mesesDecorridos=Math.max(1,Math.min(10, mesAtual<9?1:mesAtual-8));
  const rows=alunos.map(x=>{
    const cl=getClasse(x.ins.Classe,x.ins.Ano),b=DB.propinas[x.ins.IdInscricao];
    return {x,cl,pagos:Math.max(0,b.mesesDevidos-b.mesesEmFalta),devidos:b.mesesDevidos,falta:b.mesesEmFalta,valorDevido:b.divida};
  }).filter(r=>r.falta>0);
  const totalDevido=rows.reduce((s,r)=>s+r.valorDevido,0);
  let h=`<div class="prt">${prtHeader()}
    <div class="prt-title">Alunos com Propinas em Atraso</div>
    <div class="prt-sub">${esc(getCurso(t.Curso)?.Nome||t.Curso)} · Turma ${esc(t.Turma)} · ${esc(t.Classe)} · Ano ${esc(t.Ano)}</div>
    <table class="prt-tabela"><thead><tr>
      <th class="c">#</th><th class="c">Nº Processo</th><th>Nome do Aluno</th><th class="c">Sexo</th><th class="c">Idade</th>
      <th class="c">Devidos</th><th class="c">Pagos</th><th class="c">Falta</th><th class="r">Valor Devido</th></tr></thead>
    <tbody>${rows.length?rows.map((r,i)=>`<tr>
      <td class="c">${i+1}</td><td class="c">${esc(r.x.aluno.IdAluno)}</td>
      <td>${esc(r.x.aluno.Nome)}</td><td class="c">${r.x.aluno.Sexo}</td><td class="c">${idade(r.x.aluno.DataNa)}</td>
      <td class="c">${r.devidos}</td><td class="c">${r.pagos}</td>
      <td class="c"><b>${r.falta}</b></td>
      <td class="r"><b>${money(r.valorDevido)}</b></td></tr>`).join('')
    :'<tr><td colspan="9" class="c" style="padding:22px;color:#666">Sem propinas em atraso.</td></tr>'}
    </tbody>
    <tfoot><tr><td colspan="8" style="text-align:right"><b>TOTAL EM DÍVIDA:</b></td>
      <td class="r"><b>${money(totalDevido)}</b></td></tr></tfoot></table>
    ${prtAss(['O Tesoureiro','O Director de Turma','A Direcção'])}${prtFooter()}</div>`;
  imprimir(h,'Dívidas Turma '+t.Turma);
}

